  plan: string;
  role: string;
  region: string;
  currency: string;
  status: string;
  shouldRetry: boolean;
};

export function describeCheckout({
  plan,
  role,
  region,
  currency,
  status,
  shouldRetry,
}: CheckoutDescription): string {
